return ['domain'=>NULL,'plural-forms'=>'nplurals=1; plural=0;','language'=>'uz_UZ','project-id-version'=>'Babilim 1.0.0','pot-creation-date'=>'2026-10-31T05:53:37+00:00','po-revision-date'=>'2026-10-31T05:53:37+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Saytingizda o\'rnatilgan plaginlar va mavzular uchun yetishmayotgan tarjimalarni to\'ldiradi.','Translations'=>'Tarjimalar','Babilim Settings'=>'Babilim sozlamalari','Settings'=>'Sozlamalar','You are not allowed to do this.'=>'Sizga bu amalni bajarishga ruxsat berilmagan.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Kamroq komponent tanlang: har bir ishga ko\'pi bilan %1$d ta amal (siz %2$d ta tanladingiz).','That component is not installed on this site, so a translation cannot be requested for it.'=>'Bu komponent ushbu saytda o‘rnatilmagan, shuning uchun u uchun tarjima so‘rab bo‘lmaydi.','Already installed.'=>'Allaqachon o\'rnatilgan.','Downloaded and installed.'=>'Yuklab olindi va o\'rnatildi.','Babilim has not been enabled for this site yet.'=>'Babilim bu sayt uchun hali yoqilmagan.','No build is available to download for this locale.'=>'Ushbu til uchun yuklab olish mumkin bo‘lgan build mavjud emas.','Rolled back to the previous build.'=>'Oldingi build’ga qaytarildi.','Rolled back and reported.'=>'Qaytarildi va xabar berildi.','Rolled back, but the report could not be sent: %s'=>'Qaytarildi, lekin xabarni yuborib bo\'lmadi: %s','Removed.'=>'Olib tashlandi.','Translation requested.'=>'Tarjima so‘ralди.','This component was already uploaded. Babilim is checking it now.'=>'Bu komponent allaqachon yuklangan. Babilim uni hozir tekshirmoqda.','Upload cancelled.'=>'Yuklash bekor qilindi.','Upload complete — translation requested.'=>'Yuklash yakunlandi — tarjima so‘raldi.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Bu komponent versiya raqamini e’lon qilmagan, shuning uchun u uchun tarjima so‘rab bo‘lmaydi.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Bu komponent versiya raqami %d belgidan uzun, Babilim buni qayta ishlay olmaydi, shuning uchun u uchun tarjima so‘rab bo‘lmaydi.','A translation cannot be requested for that locale on this site right now.'=>'Hozir bu saytda ushbu til uchun tarjima so\'rab bo\'lmaydi.','Thank you. Your report was sent.'=>'Rahmat. Xabaringiz yuborildi.','This report does not name a valid plugin or theme and locale.'=>'Bu xabarda to\'g\'ri plagin yoki mavzu va til ko\'rsatilmagan.','Please choose a category for this report.'=>'Iltimos, bu xabar uchun turkumni tanlang.','This report is missing a valid build to report against.'=>'Ushbu hisobotda hisobot berish uchun yaroqli build yo‘q.','This build is not one this site currently knows about for this component/locale.'=>'Bu build ushbu saytga hozirda shu komponent va til uchun ma’lum bo‘lgan buildlar qatoriga kirmaydi.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'"%1$s" maydoni juda uzun: u %2$d belgidan iborat, chegara esa %3$d. Hech narsa yuborilmadi; iltimos, uni qisqartirib, qayta urinib ko\'ring.','Original string'=>'Asl satr','String context'=>'Satr konteksti','Current translation'=>'Joriy tarjima','Suggested translation'=>'Taklif etilgan tarjima','Note (optional)'=>'Izoh (ixtiyoriy)','Where you saw this (optional)'=>'Buni qayerda ko\'rdingiz (ixtiyoriy)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Babilim sinxronlash jarayoni xizmat tomonidan vaqtincha kechiktirildi (so\'rovlar chastotasi cheklangan); %s dan keyin qayta urinib ko\'riladi.','That is not a valid WordPress locale code. Nothing was saved.'=>'Bu yaroqli WordPress til kodi emas. Hech narsa saqlanmadi.','Settings saved.'=>'Sozlamalar saqlandi.','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Agar bu yoqilgan bo‘lsa, o‘chirishda ushbu saytning identifikatori ham o‘chiriladi. Keyin ushbu saytga biriktirilgan pullik litsenziyani avtomatik tiklab bo‘lmaydi; uni qaytarish uchun %s manzili orqali Babilim yordam xizmatiga murojaat qilishingiz kerak bo‘ladi.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim plagin o‘chirilganda ushbu saytning identifikatorini o‘chirishga sozlangan. Shundan so‘ng ushbu saytga biriktirilgan pullik litsenziyani avtomatik tiklab bo‘lmaydi; %s manzili orqali Babilim yordam xizmatiga murojaat qilishingiz kerak bo‘ladi. Identifikatorni saqlab qolish uchun “Bekor qilish” tugmasini bosing, Babilim sozlamalarida “O‘chirishda barcha Babilim ma’lumotlarini o‘chirish” belgisini olib tashlang va plaginni yana faolsizlantiring. Baribir faolsizlantirilsinmi?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Bu tarmoqda saytlar juda ko‘p, ularni birma-bir tekshirib bo‘lmaydi va ba’zilari plagin o‘chirilganda Babilim identifikatorini o‘chirishga sozlangan bo‘lishi mumkin. Shundan so‘ng bunday saytga biriktirilgan pullik litsenziyani avtomatik tiklab bo‘lmaydi; %s manzili orqali Babilim yordam xizmatiga murojaat qilishingiz kerak bo‘ladi. Identifikatorlarni saqlab qolish uchun “Bekor qilish” tugmasini bosing, har bir saytning Babilim sozlamalarida “O‘chirishda barcha Babilim ma’lumotlarini o‘chirish” belgisini olib tashlang va plaginni yana faolsizlantiring. Baribir faolsizlantirilsinmi?','Open Babilim settings'=>'Babilim sozlamalarini ochish','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim bu saytni tasdiqlay olmadi, shuning uchun hech narsa yuklab olinmaydi yoki o\'rnatilmaydi.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Xizmat saytingizga ulana olmadi. Ehtimol, xavfsizlik devori, xavfsizlik plagini yoki hosting qoidasi so\'rovni to\'sib qo\'ymoqda; iltimos, /wp-json/babilim/v1/challenge manziliga so\'rovlarga ruxsat bering.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Saytingizning javob berishi juda uzoq vaqt oldi. Iltimos, keyinroq qayta urinib ko\'ring va hostingingiz juda sekin yoki haddan tashqari band emasligini tekshiring.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Saytingiz javob berdi, lekin kutilgan javob emas. REST API boshqa plagin tomonidan o‘zgartirilgan bo‘lishi yoki bu endpoint keshlangan bo‘lishi mumkin; iltimos, /wp-json/babilim/v1/challenge manzilini keshlash va qayta yozishdan chiqarib qo‘ying.','Please check that your site can be reached from the internet, then try again.'=>'Iltimos, saytingizga internetdan kirish mumkinligini tekshiring va qayta urinib ko\'ring.','Re-verify'=>'Qayta tasdiqlash','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Bu sayt xizmat bir sinxronlashda qabul qiladigan hajmdan oshib ketgan, shuning uchun ba\'zi elementlar qoldirildi: %1$d ta komponent va %2$d ta til.','This site is verified.'=>'Bu sayt tasdiqlangan.','Registration restarted.'=>'Ro‘yxatdan o‘tish qayta boshlandi.','Sync complete.'=>'Sinxronlash yakunlandi.','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim bu saytni yoqmoqda va tekshirmoqda… Bu sahifani qayta yuklang yoki rejalashtirilgan tekshiruv tugashini kuting.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim yoqishni yakunlay olmadi (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'Bir vaqtning o\'zida faqat bitta PHP so\'rovini bajaradigan hosting bu bosqichni yakunlay olmaydi.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim o\'chirilgan. Boshqa hech narsa yuborilmaydi; allaqachon o\'rnatilgan tarjimalar ishlashda davom etadi.','Supplementary translation index rebuilt.'=>'Qo‘shimcha tarjimalar indeksi qayta qurildi.','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Avtomatik o‘rnatish endi o‘chirilgan; xohlasangiz, sozlamalarda uni qayta yoqing.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim bu saytdagi tilingiz uchun tarjimasi yo\'q plaginlar va mavzularni topadi hamda ularning har biriga tarjima o\'rnatadi.','Languages found on this site: %s.'=>'Bu saytda topilgan tillar: %s.','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'Mavjud tarjimalarni bir bosishda o‘rnatish, yetishmayotganlarini esa so‘rash mumkin. Shundan keyin yangi tarjimalar va yangilanishlar avtomatik o‘rnatiladi (bepul tarifda faqat bepul o‘rinni allaqachon band qilgan plagin va mavzular uchun).','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'Bepul tarif cheklangan miqdordagi plagin va mavzularni qamrab oladi; aniq kvotangiz Babilim yoqilgandan keyin Sozlamalarda ko‘rsatiladi.','What is sent when you enable Babilim'=>'Babilim yoqilganda nima yuboriladi','Enabling…'=>'Yoqilmoqda…','Enable Babilim'=>'Babilim’ni yoqish','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Yoqish tugmasini bosish orqali yuqorida sanab o\'tilgan ma\'lumotlarni Babilimga yuborishga rozilik bildirasiz.','Check again now'=>'Hozir qayta tekshirish','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim bu saytni yoqmoqda va tekshirmoqda… (oxirgi urinish: %s)','Check again'=>'Qayta tekshirish','No components synced yet.'=>'Hali hech qanday komponent sinxronlanmagan.','%1$s nothing to do.'=>'%1$s bajariladigan ish yo\'q.','%1$s %2$s.'=>'%1$s %2$s.','Bulk download:'=>'Ommaviy yuklab olish:','Bulk update:'=>'Ommaviy yangilash:','Bulk request:'=>'Ommaviy so‘rov:','per day'=>'kuniga','Wrong meaning'=>'Noto‘g‘ri ma’no','Wrong term'=>'Noto‘g‘ri atama','Broken placeholder'=>'Buzilgan joy belgisi','Wrong for this context'=>'Ushbu kontekst uchun noto‘g‘ri','Wrong plural form'=>'Noto‘g‘ri ko‘plik shakli','Negation reversed'=>'Inkor teskari qilingan','Translation does not load'=>'Tarjima yuklanmaydi','problem report categoryOther'=>'Boshqa','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'Davom etilmoqda…','Continue next batch (%d left)'=>'Keyingi to‘plamni davom ettirish (%d ta qoldi)','Search components'=>'Komponentlarni qidirish','These are the languages this site uses. You can change them in %s.'=>'Bu sayt foydalanadigan tillar. Ularni %s orqali o‘zgartirishingiz mumkin.','Upload this component?'=>'Ushbu komponent yuklansinmi?','There is no upload waiting for confirmation.'=>'Tasdiqlashni kutayotgan yuklash yo‘q.','Back'=>'Orqaga','To translate this component, Babilim needs its source.'=>'Ushbu komponentni tarjima qilish uchun Babilim uning manbasiga muhtoj.','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'%1$s (versiya %2$s) ning butun plagin yoki mavzu papkasi Babilim’ga yuklanadi.','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'Agar bu papkada kalitlar, jurnallar yoki mijoz ma’lumotlari bo‘lsa, ular ham yuklanadi. Xizmat odatiy maxfiy fayllarni (konfiguratsiya, muhit, ma’lumotlar bazasi nusxalari, jurnallar, kalitlar) olib tashlaydi, lekin hammasini topishiga kafolat bera olmaydi.','The upload is kept until you ask Babilim to delete it.'=>'Yuklangan fayllar siz Babilim’dan ularni o‘chirishni so‘ramaguningizcha saqlanadi.','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'U xizmatning xosting provayderi tomonidan saqlanadi va tarjimani yaratish uchun sun’iy intellekt modellari tomonidan qayta ishlanadi.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Asl matn va undan yaratilgan tarjimalar xuddi shu versiyani o‘rnatadigan boshqa saytlarga taqdim etiladi.','By continuing you confirm that you have the right to upload this component.'=>'Davom etish orqali ushbu komponentni yuklash huquqingiz borligini tasdiqlaysiz.','Upload and request'=>'Yuklash va so‘rash','Uploading…'=>'Yuklanmoqda…','Cancel'=>'Bekor qilish','Uploading'=>'Yuklanmoqda','There is no upload in progress.'=>'Davom etayotgan yuklash yo‘q.','Uploading part %1$d of %2$d…'=>'%2$d qismdan %1$d-qism yuklanmoqda…','Continue'=>'Davom etish','Confirm'=>'Tasdiqlash','Remove'=>'Olib tashlash','Roll back'=>'Orqaga qaytarish','Nothing to confirm.'=>'Tasdiqlash uchun hech narsa yo‘q.','Choose a language'=>'Tilni tanlang','Roll back and report'=>'Orqaga qaytarish va xabar berish','Report a problem'=>'Muammo haqida xabar berish','Nothing to choose.'=>'Tanlash uchun hech narsa yo‘q.','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Tilni tanlang.','Supplementary translations'=>'Qo‘shimcha tarjimalar','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Har bir komponentning har bir tilning umumiy standart domen qo‘shimchasiga qo‘shgan o‘z hissasi.','Component'=>'Komponent','Language'=>'Til','Included in index'=>'Indeksga kiritilgan','Entries'=>'Yozuvlar','Conflicting keys'=>'Ziddiyatli kalitlar','Yes'=>'Ha','No — component inactive'=>'Yo‘q — komponent faol emas','No — installed version differs from the active one'=>'Yo\'q — o\'rnatilgan versiya faol versiyadan farq qiladi','No — component removed'=>'Yo‘q — komponent olib tashlangan','No'=>'Yo\'q','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Buni faqat tarmoq administratori bajara oladi, chunki bu ushbu tarmoqdagi barcha saytlar uchun umumiy tarjima fayllarini o\'zgartiradi.','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim bu saytni tekshirishni yakunlay olmadi (xizmat saytga qayta ulana olmadi). Ro\'yxatdan o\'tkazish to\'xtatildi.','This site already has an active registration that can no longer be recovered automatically.'=>'Bu saytda faol ro\'yxatdan o\'tish mavjud, uni endi avtomatik tiklab bo\'lmaydi.','Restart registration'=>'Ro\'yxatdan o\'tkazishni qayta boshlash','Babilim settings'=>'Babilim sozlamalari','General'=>'Umumiy','Advanced'=>'Qo\'shimcha','Languages'=>'Tillar','Automatic installs'=>'Avtomatik o‘rnatishlar','Install available translations automatically'=>'Mavjud tarjimalarni avtomatik o‘rnatish','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'Bepul tarifda faqat bepul o‘rinlaringizdan birini allaqachon ishlatayotgan komponentlar avtomatik o‘rnatiladi, shuning uchun yangi o‘rin band qilinmaydi.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Bu sayt ko\'p saytli tarmoqning bir qismi bo\'lib, yangi tarjimalarni avtomatik o\'rnatmaydi. Allaqachon o\'rnatilgan tarjimalar baribir yangilanadi.','Custom overrides'=>'Maxsus almashtirishlar','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Hammasini tozalashda yoki ushbu plaginni o\'chirishda o\'zimning tarjima almashtirishlarimni saqlab qolish.','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'%s papkasiga qo\'ygan tarjima fayllaringiz doim Babilim fayllaridan ustun turadi. Bu belgini olib tashlamasangiz, ular saqlanadi.','Uninstall'=>'O\'chirish','Delete all Babilim data on uninstall'=>'O‘chirishda barcha Babilim ma’lumotlarini o‘chirish','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Odatda o‘chiq: plaginni o‘chirib tashlash ushbu saytning identifikatorini saqlab qoladi, shuning uchun qayta o‘rnatishda undan foydalanish mumkin.','Account'=>'Hisob','Save changes'=>'O\'zgarishlarni saqlash','Disable Babilim'=>'Babilim’ni o‘chirib qo‘yish','Installed translations are kept, but no further checks or downloads will run.'=>'O\'rnatilgan tarjimalar saqlanadi, lekin boshqa tekshiruvlar va yuklab olishlar bajarilmaydi.','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim o‘chirib qo‘yilsinmi? O‘rnatilgan tarjimalar saqlanadi, lekin boshqa tekshiruvlar yoki yuklab olishlar bajarilmaydi.','This site is not registered with Babilim yet.'=>'Bu sayt hali Babilim\'da ro\'yxatdan o\'tmagan.','This site is already licensed. Reload the page.'=>'Bu saytga allaqachon litsenziya berilgan. Sahifani qayta yuklang.','Checkout is not available for this site right now.'=>'Hozirda ushbu sayt uchun to‘lov mavjud emas.','Could not start checkout: %s'=>'To‘lovni boshlab bo‘lmadi: %s','Babilim is not enabled.'=>'Babilim yoqilmagan.','Not registered yet'=>'Hali ro‘yxatdan o‘tmagan','Not verified'=>'Tasdiqlanmagan','Verified'=>'Tasdiqlangan','Status'=>'Holati','Licensed'=>'Litsenziyalangan','Partner'=>'Hamkor','Free'=>'Bepul','License'=>'Litsenziya','Upgrade this site'=>'Ushbu saytni yangilash','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Ushbu sayt uchun bir martalik xarid: %1$s %2$s. Barcha kelgusi tarjima yangilanishlarini o\'z ichiga oladi. To\'lovni Paddle yangi yorliqda amalga oshiradi.','This issues a new restore code and the previous one stops working. Continue?'=>'Bu yangi tiklash kodini beradi va avvalgisi ishlamay qoladi. Davom etilsinmi?','Show a new restore code'=>'Yangi tiklash kodini ko‘rsatish','rc_…'=>'rc_…','Restore code'=>'Tiklash kodi','Restore purchase'=>'Xaridni tiklash','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Bu domen uchun avval litsenziya sotib olganmisiz? To‘lov paytida olgan tiklash kodingizni kiriting.','That does not look like a restore code.'=>'Bu tiklash kodiga o‘xshamaydi.','This restore code was not recognised for this site.'=>'Bu tiklash kodi ushbu sayt uchun tanilmadi.','Too many attempts. Try again tomorrow.'=>'Juda ko\'p urinish. Ertaga qayta urinib ko\'ring.','This site must be verified first.'=>'Avval ushbu sayt tasdiqlanishi kerak.','Could not restore the purchase: %s'=>'Xaridni tiklab bo\'lmadi: %s','Purchase restored. This site is now licensed.'=>'Xarid tiklandi. Endi bu sayt litsenziyalangan.','This site has no purchase to show a code for.'=>'Bu saytda kod ko\'rsatiladigan xarid yo\'q.','Could not show a new restore code: %s'=>'Yangi tiklash kodini ko‘rsatib bo‘lmadi: %s','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Yangi tiklash kodingiz: %s. Uni xavfsiz joyda saqlang — avvalgi kod endi ishlamaydi.','What is sent when Babilim checks this site'=>'Babilim bu saytni tekshirganda nima yuboriladi','(detected)'=>'(aniqlangan)','No language is managed yet.'=>'Hozircha birorta til boshqarilmaydi.','Babilim adds translations for every language checked here.'=>'Babilim bu yerda belgilangan har bir til uchun tarjimalar qo\'shadi.','Add another language'=>'Yana til qo\'shish','Choose a language…'=>'Tilni tanlang…','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Xizmatdan WordPress.org lokallarining to\'liq ro\'yxatini yuklab bo\'lmadi, shuning uchun hozir boshqa til qo\'shib bo\'lmaydi.','Theme'=>'Mavzu','Plugin'=>'Plagin','Free quota'=>'Bepul kvota','Downloads: %1$d/%2$d (%3$s)'=>'Yuklab olishlar: %1$d/%2$d (%3$s)','Supplementary translation index'=>'Qo‘shimcha tarjimalar indeksi','Built'=>'Yaratilgan','Included'=>'Kiritilgan','Excluded'=>'Chiqarib tashlangan','Already in WordPress core'=>'WordPress yadrosida allaqachon mavjud','Supplementary translation maintenance'=>'Qo\'shimcha tarjimalarga xizmat ko\'rsatish','Maintenance status is not available right now.'=>'Xizmat ko\'rsatish holati hozir mavjud emas.','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'%1$s da tozalash to‘xtatildi: %2$s. Hech narsa o‘chirilmadi.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'So‘nggi tozalash %1$s: %2$d ta yangi belgilandi, %3$d ta fayl o‘chirildi, %4$d ta yozuv olib tashlandi.','No cleanup has run yet.'=>'Hozircha tozalash bajarilmagan.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Tarjimalar indeksiga yozish %1$s da (%2$s) boshqa so\'rov bilan to\'qnashdi va qo\'llanmadi; eng so\'nggi versiya saqlab qolindi.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Tarjimalar indeksiga %1$s da (%2$s) yozishni yakunlab bo\'lmadi va u qo\'llanmadi (%3$s).','Maintenance'=>'Texnik xizmat','Rebuild index now'=>'Indeksni hozir qayta qurish','Sweep now'=>'Hozir skanerlash','Danger zone'=>'Xavfli hudud','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Babilim bu saytdagi barcha plagin va mavzular uchun o\'rnatgan barcha til fayllarini olib tashlaydi.','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Babilim o\'rnatgan hamma narsa olib tashlansinmi? Bu Babilim ushbu saytdagi barcha plagin va mavzular uchun o\'rnatgan barcha til fayllarini o\'chiradi.','Remove everything Babilim installed'=>'Babilim o\'rnatgan hamma narsani olib tashlash','This string is too long to be sent as a report, so no report form is offered for it.'=>'Bu satr hisobot sifatida yuborish uchun juda uzun, shuning uchun u uchun hisobot shakli taklif etilmaydi.','Category'=>'Toifa','Choose a category…'=>'Toifani tanlang…','Roll back and send report'=>'Qaytarish va hisobot yuborish','Send report'=>'Hisobot yuborish','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Ushbu komponent matnining bir qismi muallif tomonidan qattiq kodlangan va til paketi orqali tarjima qilib bo‘lmaydi.','WordPress.org'=>'WordPress.org','Bundled with the theme'=>'Mavzu bilan birga keladi','Bundled with the plugin'=>'Plagin bilan birga keladi','Upload was not accepted'=>'Yuklash qabul qilinmadi','Upload expired before it finished'=>'Yuklash tugamasdan muddati tugadi','No translation'=>'Tarjima yo\'q','Upload in progress — continue or cancel'=>'Yuklash davom etmoqda — davom ettiring yoki bekor qiling','Scheduled, waiting to be processed'=>'Rejalashtirilgan, qayta ishlashni kutmoqda','Translating…'=>'Tarjima qilinmoqda…','Translation failed'=>'Tarjima muvaffaqiyatsiz tugadi','Free quota used'=>'Bepul kvota ishlatilgan','Needs a paid license'=>'Pullik litsenziya kerak','Not supported'=>'Qo\'llab-quvvatlanmaydi','Status unknown'=>'Holati noma’lum','translation statusInstalled'=>'O\'rnatilgan','Update available'=>'Yangilanish mavjud','Removed after a failed integrity check'=>'Yaxlitlikni tekshirish muvaffaqiyatsiz tugagani sababli olib tashlandi','Installed · built for %s, new version scheduled'=>'O\'rnatilgan · %s uchun yaratilgan, yangi versiya rejalashtirilgan','Installed · built for a different version, new version scheduled'=>'O\'rnatilgan · boshqa versiya uchun yaratilgan, yangi versiya rejalashtirilgan','Installed · built for %s, translating the new version…'=>'O\'rnatilgan · %s uchun yaratilgan, yangi versiya tarjima qilinmoqda…','Installed · built for a different version, translating the new version…'=>'O\'rnatilgan · boshqa versiya uchun yaratilgan, yangi versiya tarjima qilinmoqda…','Installed · built for %1$s, this site has %2$s'=>'O\'rnatilgan · %1$s uchun yaratilgan, bu saytda %2$s mavjud','Installed · built for %s'=>'O\'rnatilgan · %s uchun yaratilgan','Installed · built for a different version'=>'O\'rnatilgan · boshqa versiya uchun yaratilgan','Installed · built for %s, new version failed'=>'O\'rnatilgan · %s uchun tuzilgan, yangi versiya muvaffaqiyatsiz','Installed · built for a different version, new version failed'=>'O\'rnatilgan · boshqa versiya uchun tuzilgan, yangi versiya muvaffaqiyatsiz','Installed · built for %s, new version needs a paid license'=>'O‘rnatilgan · %s uchun yaratilgan, yangi versiya pullik litsenziyani talab qiladi','Installed · built for a different version, new version needs a paid license'=>'O‘rnatilgan · boshqa versiya uchun yaratilgan, yangi versiya pullik litsenziyani talab qiladi','Installed · built for %s, free quota used'=>'O‘rnatilgan · %s uchun yaratilgan, bepul kvota ishlatilgan','Installed · built for a different version, free quota used'=>'O‘rnatilgan · boshqa versiya uchun yaratilgan, bepul kvota ishlatilgan','translation statusAvailable'=>'Mavjud','Installed · %s'=>'O\'rnatilgan · %s','Available · %s'=>'Mavjud · %s','Update'=>'Yangilash','Download'=>'Yuklab olish','Updating…'=>'Yangilanmoqda…','Downloading…'=>'Yuklab olinmoqda…','Retry request'=>'So‘rovni qayta yuborish','Request newer translation'=>'Yangiroq tarjimani so\'rash','Request translation'=>'Tarjima so‘rash','Requesting…'=>'So\'ralmoqda…','Requesting a translation uses one of your free slots, unless this component already uses one. A failed translation does not give the slot back.'=>'Tarjima so‘rash bepul o‘rinlaringizdan birini sarflaydi, agar bu komponent allaqachon birini ishlatmayotgan bo‘lsa. Muvaffaqiyatsiz tarjima o‘rinni qaytarmaydi.','If this component does not use one of your free slots yet, requesting a translation uses one. A failed translation does not give the slot back. Continue?'=>'Agar bu komponent hali bepul o‘rinlaringizdan birini ishlatmayotgan bo‘lsa, tarjima so‘rash birini sarflaydi. Muvaffaqiyatsiz tarjima o‘rinni qaytarmaydi. Davom etasizmi?','No plugins or themes found.'=>'Hech qanday plagin yoki mavzu topilmadi.','Clear filters'=>'Filtrlarni tozalash','No components match these filters. %s'=>'Bu filtrlarga mos komponent yo\'q. %s','Select all'=>'Hammasini tanlash','All'=>'Barchasi','Available'=>'Mavjud','Updates'=>'Yangilanishlar','Requestable'=>'So‘rash mumkin','Installed'=>'O\'rnatilgan','Plugins'=>'Plaginlar','Themes'=>'Mavzular','All languages'=>'Barcha tillar','Language:'=>'Til:','Bulk actions apply to every matching language of each selected component.'=>'Ommaviy amallar tanlangan har bir komponentning barcha mos tillariga qo‘llanadi.','Bulk actions apply only to the selected language of each selected component.'=>'Ommaviy amallar tanlangan har bir komponentning faqat tanlangan tiliga qo‘llanadi.','Version %s'=>'Versiya %s','Theme · %s'=>'Mavzu · %s','Plugin · %s'=>'Plagin · %s','Remove the %2$s translation of %1$s from this site?'=>'%1$s komponentining %2$s tilidagi tarjimasi bu saytdan olib tashlansinmi?','Roll back the %2$s translation of %1$s to the previous build?'=>'%1$s komponentining %2$s tilidagi tarjimasi oldingi yig‘maga qaytarilsinmi?','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','The registration challenge is not in the expected form.'=>'Ro\'yxatdan o\'tish uchun tekshiruv topshirig\'i kutilgan shaklda emas.','That is not a valid build identifier.'=>'Bu yaroqli yig‘ma identifikatori emas.','Refusing to write outside the Babilim language-file directory.'=>'Babilim til fayllari katalogidan tashqariga yozish rad etildi.','Could not write the downloaded package to disk.'=>'Yuklab olingan paketni diskka yozib bo\'lmadi.','Unexpected HTTP %d response.'=>'Kutilmagan HTTP %d javobi.','This site\'s URL, so the service can verify you own it.'=>'Ushbu saytning URL manzili, shunda xizmat sizga tegishli ekanini tekshira oladi.','Your WordPress version, to serve compatible translation files.'=>'WordPress versiyangiz, mos tarjima fayllarini taqdim etish uchun.','Your PHP version, for compatibility.'=>'PHP versiyangiz, moslik uchun.','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Ushbu plaginning o\'z versiyasi, shunda u juda eski bo\'lib, xizmat bilan aloqa qila olmasa, xizmat uni yangilashni aytishi mumkin.','This site\'s configured locale.'=>'Ushbu saytning sozlangan lokali.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Ushbu saytda ishlatilayotgan barcha lokallar (sayt lokali, o\'rnatilgan til paketlari, foydalanuvchi lokallari va qo\'lda qo\'shganlaringiz). Barcha lokallarga bir xil munosabatda bo\'linadi.','(a public key generated for this site)'=>'(ushbu sayt uchun yaratilgan ochiq kalit)','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Ushbu saytning o\'rnatish ochiq kaliti, so\'rovlar haqiqatan ham shu saytdan kelganini isbotlash uchun ishlatiladi. Faqat ochiq qismi yuboriladi.','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Har bir o‘rnatilgan plagin/mavzu: uning slugi, versiyasi, matn domen(lar)i, wp.org ro‘yxatida ekanligi, o‘zining kiritilgan lokallari va siz uchun Babilim tarjimasi allaqachon o‘rnatilgan lokallar.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: that component\'s entire directory, as a zip.'=>'Faqat WordPress.org’da bo‘lmagan plagin yoki mavzu uchun yuklashni tasdiqlaganingizda: shu komponentning butun katalogi zip ko‘rinishida.','(generic codes and coordinates only)'=>'(faqat umumiy kodlar va koordinatalar)','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'Kutilayotgan 20 tagacha diagnostika hodisalari (masalan, yaxlitlikni tekshirishdan o‘tmagan fayl), har biri faqat kod, komponent va lokaldan iborat, hech qachon matn mazmuni yoki tarjima qilingan matnni o‘z ichiga olmaydi.','Unsafe locale: %s'=>'Xavfli lokal: %s','Manifest unavailable: %s'=>'Manifest mavjud emas: %s','Could not determine active components; the existing merged index was left unchanged.'=>'Faol komponentlarni aniqlab bo\'lmadi; mavjud birlashtirilgan indeks o\'zgartirilmadi.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'O\'rnatilgan plagin/mavzularni aniqlab bo\'lmadi; tozalash o\'tkazib yuborildi, hech narsa o\'chirilmadi.','Sweep aborted without orphaning anything: %s.'=>'Skanerlash hech narsani yetim qoldirmasdan to‘xtatildi: %s.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Tozalash bajarildi, ammo uning ba’zi o‘zgarishlarini tarjimalar indeksiga yozib bo‘lmadi; keyingi tozalash ularni qayta urinib ko‘radi.','component kind in the sweep brake messagetheme'=>'mavzu','component kind in the sweep brake messageplugin'=>'plagin','it would orphan every managed %1$s component (%2$d of %2$d)'=>'u boshqariladigan barcha %1$s komponentlarini yetim qoldiradi (%2$d tadan %2$d tasi)','it would orphan %1$d of %2$d managed components (more than half)'=>'u boshqariladigan komponentlarning %2$d tasidan %1$d tasini yetim qoldiradi (yarmidan ko‘pi)','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'\'%s\' uchun birlashtirilgan indeks qayta qurildi, ammo tarjimalar indeksi uni qayd eta olmadi; keyingi qayta qurishda yana urinib ko‘riladi.','Could not write the staged merged index.'=>'Bosqichma-bosqich birlashtirilgan indeksni yozib bo‘lmadi.','Re-parsed entry count did not match the built index.'=>'Qayta tahlil qilingan yozuvlar soni tuzilgan indeksga mos kelmadi.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'\'%s\' uchun birlashtirilgan indeksni joyiga ko‘chirib bo‘lmadi; oldingi taqdim etilgan indeks (agar bo‘lsa) yarim yangilangan holda qoldirilmasdan o‘chirildi. Keyingi muvaffaqiyatli qayta qurishgacha bu til uchun standart domen qo‘shimchasi taqdim etilmaydi.','Could not open zip: %s'=>'Zip faylni ochib bo\'lmadi: %s','Zip has no manifest.json.'=>'Zip ichida manifest.json yo‘q.','manifest.json in the zip is not valid JSON.'=>'Zip ichidagi manifest.json yaroqli JSON emas.','manifest.json\'s \'%s\' does not match the expected value.'=>'manifest.json dagi \'%s\' kutilgan qiymatga mos kelmaydi.','Another installation is running; try again in a moment.'=>'Boshqa o\'rnatish jarayoni ishlamoqda; birozdan so\'ng qayta urinib ko\'ring.','Not a valid server_build_id: %s'=>'Yaroqli server_build_id emas: %s','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Paket manifestidagi \'%1$s\' turi so‘ralgan \'%2$s\' turiga mos kelmaydi.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Paketning matn domeni \'%1$s\' ushbu saytdagi komponent nusxasining (\'%2$s\') matn domeniga mos kelmaydi, shuning uchun o‘rnatilmadi.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Berilgan \'%1$s\' domeni paket manifestining o‘z slug\'i \'%2$s\' ga ham, text_domain \'%3$s\' ga ham mos kelmaydi.','Unsafe slug: %s'=>'Xavfli slug: %s','Unsafe text_domain: %s'=>'Xavfli text_domain: %s','The package has no %s for its own text domain.'=>'Paketda o‘zining matn domeni uchun %s yo‘q.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json da \'%s\' yo‘q yoki yaroqsiz.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json da \'entries\' yo‘q yoki yaroqsiz.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json da \'files\' yo‘q yoki yaroqsiz.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json da \'extra_domains\' yo‘q yoki yaroqsiz.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json da \'build_no\' yo‘q yoki yaroqsiz.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'manifest.json dagi \'server_build_id\' yaroqli build id emas.','manifest.json\'s \'contract\' is not a valid version string.'=>'manifest.json dagi \'contract\' yaroqli versiya qatori emas.','manifest.json\'s \'status\' must be \'published\'.'=>'manifest.json dagi \'status\' \'published\' bo‘lishi kerak.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'manifest.json dagi \'kind\' \'plugin\' yoki \'theme\' bo‘lishi kerak.','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json da yaroqsiz \'default_domain_entries\' bor.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json da yaroqsiz \'default_domain_files\' bor.','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest da \'%s\' yo‘q yoki yaroqsiz.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'expected_manifest dagi \'server_build_id\' yaroqli build id emas.','No record for %s'=>'%s uchun yozuv yo‘q','One or more served files no longer match the manifest.'=>'Taqdim etilgan bir yoki bir nechta fayl endi manifestga mos kelmaydi.','No previous build to roll back to.'=>'Orqaga qaytariladigan oldingi build yo‘q.','The change could not be recorded in the translation index; please try again.'=>'O‘zgarishni tarjimalar indeksiga yozib bo‘lmadi; qayta urinib ko‘ring.','Unknown kind: %s'=>'Noma’lum tur: %s','Unsafe domain: %s'=>'Xavfli domen: %s','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'\'%1$s\' matn domeni (%2$s) boshqa o‘rnatilgan komponent (%3$s) uchun allaqachon taqdim etilgan; hech narsa o‘rnatilmadi.','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Orqaga qaytarish \'%1$s\' (%2$s) faylini ustiga yozadi, u hozir boshqa o‘rnatilgan komponent (%3$s) uchun taqdim etilgan; hech narsa o‘zgartirilmadi.','Zip is missing expected file: %s'=>'Zip arxivda kutilgan fayl yo‘q: %s','sha256 mismatch for %s'=>'%s uchun sha256 mos kelmadi','The package declares no main translation file.'=>'Paketda asosiy tarjima fayli ko‘rsatilmagan.','Zip is missing expected default file: %s'=>'Zip arxivda kutilgan standart fayl yo‘q: %s','sha256 mismatch for default/%s'=>'default/%s uchun sha256 mos kelmadi','Could not stage %s'=>'%s faylini tayyorlab bo‘lmadi','Could not stage default/%s'=>'default/%s faylini tayyorlab bo‘lmadi','Entry count mismatch for %s'=>'%s uchun yozuvlar soni mos kelmadi','Could not verify entry count for %s'=>'%s uchun yozuvlar sonini tekshirib bo‘lmadi','l10n.php entry count mismatch for %s'=>'%s uchun l10n.php yozuvlari soni mos kelmadi','Default supplement entry count mismatch.'=>'Standart qo‘shimchadagi yozuvlar soni mos kelmadi.','The package produced no servable main translation file.'=>'Paket foydalanish uchun taqdim etishga yaroqli asosiy tarjima faylini yaratmadi.','Could not prepare %s for rollback.'=>'%s ni orqaga qaytarish uchun tayyorlab bo‘lmadi.','Could not back up %s before replacing it.'=>'%s almashtirilishidan oldin uning zaxira nusxasini yaratib bo‘lmadi.','Could not move %s into place.'=>'%s faylini joyiga ko‘chirib bo‘lmadi.','Could not read %s back after moving it into place.'=>'%s joyiga ko‘chirilgandan keyin uni qayta o‘qib bo‘lmadi.','English (United States)'=>'Ingliz tili (Amerika Qo‘shma Shtatlari)','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest mavjud emas: %s','could not read _manifest.json: %s'=>'_manifest.json faylini o‘qib bo‘lmadi: %s','failed to parse _manifest.json: %s'=>'_manifest.json faylini tahlil qilib bo‘lmadi: %s','_manifest.json has an unexpected structure'=>'_manifest.json kutilmagan tuzilishga ega','Could not create the package archive.'=>'Paket arxivini yaratib bo‘lmadi.','No writable temporary directory is available for packaging.'=>'Paketlash uchun yozish mumkin bo‘lgan vaqtinchalik katalog mavjud emas.','A file in the component could not be read, so it was not packaged.'=>'Komponentdagi bitta fayl o‘qib bo‘lmadi, shuning uchun u paketga kiritilmadi.','Only plugins and themes can be packaged.'=>'Faqat plaginlar va mavzularni paketlash mumkin.','The component\'s main file was not found.'=>'Komponentning asosiy fayli topilmadi.','The component is not inside the plugins or themes directory.'=>'Komponent plaginlar yoki mavzular katalogi ichida emas.','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim bu qadam uchun ajratilgan vaqtdan oshib ketdi va keyingi tekshiruvda davom etadi.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim bu saytni tasdiqlay olmadi, shuning uchun tasdiqlash muvaffaqiyatli bo‘lmaguncha hech narsa yuklab olinmaydi yoki o‘rnatilmaydi.','Registration response was missing required fields.'=>'Ro‘yxatdan o‘tkazish javobida zarur maydonlar yetishmadi.','No pending challenge to verify.'=>'Tasdiqlash uchun kutilayotgan chaqiriq yo‘q.','Verify response was missing site_token.'=>'Tasdiqlash javobida site_token yetishmadi.','No site id is on file to rotate a token for.'=>'Tokenni almashtirish uchun fayllarda saqlangan sayt identifikatori yo‘q.','Rotate-token response was missing site_token.'=>'Tokenni almashtirish javobida site_token yetishmadi.','nonce must be a hexadecimal string.'=>'nonce o‘n oltilik satr bo‘lishi kerak.','No pending challenge for this nonce.'=>'Bu nonce uchun kutilayotgan so‘rov yo‘q.','Too many requests.'=>'Juda ko‘p so‘rovlar.','The service asked this site to wait before syncing again.'=>'Xizmat bu saytdan qayta sinxronlashdan oldin kutishni so‘radi.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Bu saytda %2$d ta tilda %1$d ta komponent bor, buning uchun %3$d ta tekshiruv guruhi kerak; Babilim har bir ishga tushirishda ko‘pi bilan %4$d tasini bajara oladi. Sozlamalarda boshqariladigan tillarni kamaytiring yoki foydalanilmayotgan plagin va mavzularni faolsizlantiring, so‘ng hozir Qayta tekshirish tugmasini bosing.','Babilim could not finish checking this site.'=>'Babilim bu saytni tekshirishni yakunlay olmadi.','This site\'s address is too long for Babilim to register.'=>'Bu saytning manzili Babilim ro‘yxatdan o‘tkazishi uchun juda uzun.','This site\'s locale code is not one Babilim can register.'=>'Bu saytning til kodini Babilim ro‘yxatdan o‘tkaza olmaydi.','The download response was missing a usable location.'=>'Yuklab olish javobida foydalanish mumkin bo‘lgan manzil yo‘q edi.','The service\'s upload offer was incomplete.'=>'Xizmatning yuklash taklifi to‘liq emas edi.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Bu komponent xizmat qabul qiladigan hajmdan katta, shuning uchun uni yuklab bo‘lmaydi.','The packaged component could not be read.'=>'Paketlangan komponentni o‘qib bo‘lmadi.','A part of the upload kept failing, so the upload was cancelled.'=>'Yuklashning bir qismi qayta-qayta muvaffaqiyatsiz bo‘ldi, shuning uchun yuklash bekor qilindi.','Could not read: %s'=>'O‘qib bo‘lmadi: %s']];